        if n < 2:
            return False
        i = 2
        while i * i <= n:
            if n % i == 0:
                return False
            i += 1
        return True
    result = []
    for i, ch in enumerate(s):
        if is_prime(i):
            result.append(ch)
    return ''.join(result)
