```python
def spread_chars(s):
    from collections import Counter
    if not s:
        return ''
    counts = Counter(s)
    heap = [(-c, ch) for ch, c in counts.items()]
    import heapq
    heapq.heapify(heap)
    out = []
    while heap:
        neg, ch = heapq.heappop(heap)
        if out and out[-1] == ch:
            if not heap:
                return ''
            n, c = heapq.heappop(heap)
            out.append(c)
            if n + 1:
                heapq.heappush(heap, (n + 1, c))
            heapq.heappush(heap, (neg, ch))
        else:
            out.append(ch)
            if neg + 1:
                heapq.heappush(heap, (neg + 1, ch))
    return ''.join(out)
```

