    undo_stack = []
    for op in ops:
        if op[0] == 'undo':
            if undo_stack:
                stock = undo_stack.pop()
        else:
            item, qty = op[1], op[2]
            stock[item] = stock.get(item, 0) + qty
            undo_stack.append(stock.copy())
    return stock
