def eval_postfix_digits(expr):
    stack = []
    for ch in expr:
        if ch in "0123456789":
            stack.append(int(ch))
        else:
            b, a = stack.pop(), stack.pop()
            if ch == "+":
                stack.append(a + b)
            elif ch == "-":
                stack.append(a - b)
            elif ch == "*":
                stack.append(a * b)
            else:
                stack.append(a // b)
    return stack[0]
```

